import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[5]/'scripts'))
from write_fipi50_annotations import save

save('3E3293','a∈(1/4;1/2] ∪ [11/2;23/4)',[
 ('Установить область и выделить нули множителей','На [0;3] нужно x>1/4 и (x-3)²≥(a-3)². Произведение равно нулю, если ln(4x-1)=0 либо радиканд равен нулю, но оба множителя должны быть определены.',['domain','factor'],['condition']),
 ('Проверить логарифмический корень на область','ln(4x-1)=0 ⇒ x=1/2. Он допустим тогда и только тогда, когда |a-3|≤5/2.',['log','domain'],['s1']),
 ('Найти допустимые корни радиканда на заданном отрезке','Пусть d=|a-3|. Нули x=3±d. При d>0 в (1/4;3] может быть только 3-d, и он допустим при d<11/4. При d=0 оба совпадают в x=3.',['quad','filter'],['condition','s1']),
 ('Посчитать различные корни и учесть совпадение','При 0≤d<5/2 два различных корня: 1/2 и 3-d. При d=5/2 они совпадают. При 5/2<d<11/4 остаётся только 3-d. При d≥11/4 корней нет. Ровно один при 5/2≤|a-3|<11/4.',['count'],['s2','s3']),
 ('Перевести двойное ограничение модуля в интервалы параметра','Получаем (1/4;1/2]∪[11/2;23/4). Границы 1/4 и 23/4 исключены из-за неопределённого логарифма при x=1/4.',['absineq'],['s4'])],
 [('domain','Устанавливать совместную область логарифма и корня','Потребовать положительность аргумента логарифма и неотрицательность радиканда; нулевой множитель не делает неопределённый другой множитель допустимым.'),
 ('factor','Решать уравнение через нулевое произведение','Разделить нули произведения по множителям на общей области определения и объединить допустимые корни.'),
 ('log','Решать простейшее логарифмическое уравнение','Использовать определение логарифма при допустимом основании и положительном аргументе.'),
 ('quad','Решать квадратное уравнение выделением квадрата','Переписать выражение как полный квадрат и найти обе ветви корней с учётом действительности.'),
 ('filter','Отбирать алгебраические решения по заданной области','Проверить кандидатов на область определения и принадлежность заданному промежутку.'),
 ('count','Считать различные корни с учётом ветвей и границ','Отдельно проверить допустимость, совпадения и граничные случаи; не считать один корень дважды.'),
 ('absineq','Решать двойное неравенство для модуля линейного выражения','Перевести ограничения на расстояние от точки в объединение промежутков с правильными границами.')],
 [('Найти нули двух множителей и посчитать допустимые различные корни',[1,2,3,4,5])])

save('8F25eA','5',[
 ('Применить формулу синуса двойного угла','sin 144°=2 sin72° cos72°, причём sin144°≠0.',['trig'],['condition']),
 ('Сократить одинаковый ненулевой множитель','10 sin72° cos72°/sin144°=5.',['cancel'],['s1'])],
 [('trig','Преобразовывать тригонометрические выражения тождествами','Применять формулу двойного угла для замены произведения синуса и косинуса или синуса удвоенного аргумента.'),
 ('cancel','Сокращать дробь с ненулевым общим множителем','Выделить общий множитель числителя и знаменателя, проверить его ненулевость и сократить.')],
 [('Заменить знаменатель формулой двойного угла',[1,2])])

save('336660','6',[
 ('Найти производную на области определения','x>0; весь отрезок [1/16;5/16] допустим. y′=1/x-8.',['derivlog','domain'],['condition']),
 ('Найти критическую точку и определить монотонность','y′=0 при x=1/8. Производная положительна слева и отрицательна справа, поэтому функция возрастает до 1/8 и убывает после него; точка внутри отрезка.',['critical','sign'],['condition','s1']),
 ('Вычислить глобальный максимум на отрезке','y(1/8)=ln1-1+7=6; монотонность доказывает, что на концах значения не больше.',['extreme'],['s2'])],
 [('derivlog','Дифференцировать логарифм линейного аргумента','Использовать (ln u)′=u′/u при u>0 и правило суммы.'),
 ('domain','Устанавливать область определения логарифмической функции','Потребовать положительность аргумента и проверить принадлежность рассматриваемого промежутка области.'),
 ('critical','Находить стационарные точки по нулю производной','Решить y′=0 на области определения и отобрать точки нужного промежутка.'),
 ('sign','Устанавливать монотонность по знаку производной','Определить знак производной на промежутках и сделать вывод о возрастании/убывании функции.'),
 ('extreme','Находить глобальный экстремум на отрезке','Использовать монотонность или сравнение критических точек и концов и вычислить соответствующее значение функции.')],
 [('Исследовать знак производной и вычислить максимум',[1,2,3])])

save('B43678','x∈(-∞;0) ∪ {1/3} ∪ (2/3;+∞)',[
 ('Ввести положительную показательную замену и сохранить запрещённые значения','t=8^x>0. Тогда 2·8^(x-1)=t/4,64^x=t². Знаменатели исключают t=1 и t=4.',['expsub','domain'],['condition']),
 ('Привести разность частей к одной дроби','t/(t-4)-3/(t-1)-8/((t-1)(t-4))=(t-2)²/((t-1)(t-4)). Требуется эта дробь ≥0.',['rational'],['s1']),
 ('Решить рациональное неравенство','При t>0 и t≠1,4 знаменатель положителен на (0;1) и (4;+∞); отдельно числитель обнуляется при t=2. Ответ по t: (0;1)∪{2}∪(4;+∞).',['signs'],['s1','s2']),
 ('Вернуться к x по возрастанию 8^x','t<1 ⇒ x<0; t=2 ⇒ x=1/3; t>4 ⇒ x>2/3. Запрещённые границы не включаются.',['expineq'],['s3'])],
 [('expsub','Заменять показатели степенной переменной','Ввести t=b^x>0 и выразить согласованные степени через t при положительном b≠1.'),
 ('domain','Сохранять ограничения знаменателей','Выделить значения, при которых исходные знаменатели равны нулю, и исключить их после преобразований.'),
 ('rational','Приводить рациональные выражения к общей дроби','Разложить знаменатели и объединить дроби с общим знаменателем, сохранив исходную область.'),
 ('signs','Решать рациональное неравенство методом интервалов','Установить нули и полюса, определить знак по промежуткам, включить допустимые нули и исключить полюса.'),
 ('expineq','Решать показательное неравенство по монотонности','Перейти от ограничения b^x к ограничению x с учётом того, больше ли основание единицы.')],
 [('Показательная замена и метод интервалов',[1,2,3,4])])

save('19FBCF','2',[
 ('Привести степени к общему основанию и приравнять показатели','9^(2x)=3^(4x); при основании 3 получаем x+6=4x.',['exp'],['condition']),
 ('Решить линейное уравнение и проверить','x=2. Тогда обе части равны 3^8; решение единственно.',['lin'],['s1'])],
 [('exp','Сводить показательное уравнение к равенству показателей','При одинаковом положительном основании, отличном от единицы, заменить равенство степеней равенством показателей; предварительно согласовать основания.'),
 ('lin','Решать линейное уравнение с числовыми коэффициентами','Преобразовать аффинное равенство одной переменной и получить его множество решений; переносы и деление входят в одно действие.')],
 [('Привести к основанию 3 и решить уравнение показателей',[1,2])])

save('696D47','x∈(-∞;-1] ∪ [1;5/2) ∪ (5/2;+∞)',[
 ('Найти область определения и знак знаменателя','x²>0 ⇒ x≠0. Второй аргумент 2x²-10x+12,5=2(x-5/2)²>0 ⇒ x≠5/2. На этой области квадрат логарифма плюс 1 строго положителен.',['domain','positive'],['condition']),
 ('Определить знак числителя переходом к натуральным логарифмам','log₂x²-log₃x²=(1/ln2-1/ln3)ln(x²). Коэффициент положителен, потому что ln3>ln2>0. Неравенство равносильно ln(x²)≥0.',['base','positive'],['s1']),
 ('Решить неравенство логарифма и учесть область','ln(x²)≥0 ⇔ x²≥1 ⇔ x≤-1 или x≥1. Исключаем 5/2, получаем (-∞;-1]∪[1;5/2)∪(5/2;+∞).',['logineq','sets'],['s1','s2'])],
 [('domain','Устанавливать область определения логарифмического выражения','Потребовать положительность каждого аргумента логарифма и допустимость оснований; сохранить все исключения.'),
 ('positive','Сводить знак дроби к знаку числителя','При доказанно положительном знаменателе решать неравенство только для числителя; условие положительности не опускать.'),
 ('base','Переходить к общему основанию логарифмов','Использовать log_b u=ln u/ln b при u>0,b>0,b≠1 и сохранить знак постоянных коэффициентов.'),
 ('logineq','Решать логарифмическое неравенство по монотонности','Перейти от сравнения логарифма к сравнению положительного аргумента с учётом основания.'),
 ('sets','Пересекать множества допустимых значений','Совместить ограничения и правильно включить или исключить граничные точки.')],
 [('Доказать положительность знаменателя и определить знак числителя',[1,2,3])])

save('221C18','-83',[
 ('Найти производную на рассматриваемом отрезке','При x∈[1;50] имеем x>0. y=x^(3/2)-9x+25, y′=(3/2)√x-9.',['powerderiv'],['condition']),
 ('Найти единственную стационарную точку','(3/2)√x-9=0 ⇒ √x=6 ⇒ x=36, точка лежит в [1;50].',['critical'],['s1','condition']),
 ('Установить глобальный минимум и вычислить его','Производная отрицательна при 1≤x<36 и положительна при 36<x≤50. Минимум в x=36: 36·6-9·36+25=-83.',['sign','extreme'],['s1','s2'])],
 [('powerderiv','Дифференцировать степенную функцию и сумму','Использовать (x^p)′=p x^(p-1) на допустимой области и линейность производной.'),
 ('critical','Находить стационарные точки по нулю производной','Решить y′=0 на области определения и отобрать точки нужного промежутка.'),
 ('sign','Устанавливать монотонность по знаку производной','Определить знак производной на промежутках и сделать вывод о возрастании/убывании функции.'),
 ('extreme','Находить глобальный экстремум на отрезке','Использовать монотонность или сравнение критических точек и концов и вычислить соответствующее значение функции.')],
 [('Использовать знак производной на отрезке',[1,2,3])])

save('8F61E2','a∈(-∞;-3) ∪ {-1/3;0;1/3} ∪ (3;+∞)',[
 ('Снять равные квадратные корни с сохранением области','При |y|≤6 и |ax|≤6 равенство корней эквивалентно y²=a²x², то есть y=ax или y=-ax. Второе уравнение задаёт окружность x²+y²=2x+6y.',['radical','domain'],['condition']),
 ('Найти пересечение каждой прямой y=mx с окружностью','Для m=a или -a: (1+m²)x²=2(1+3m)x. Всегда есть O=(0,0); второй кандидат x_m=2(1+3m)/(1+m²), y_m=m x_m. Он совпадает с O только при m=-1/3.',['sub','factor'],['s1']),
 ('Проверить радикальную область для второго кандидата','Для y_m=2m(1+3m)/(1+m²) условие y_m≤6 равносильно m≤3. Условие y_m≥-6 выполняется всегда, так как 12m²+2m+6>0. Поэтому ненулевой кандидат допустим ровно при m≤3,m≠-1/3.',['rationalineq'],['s1','s2']),
 ('Учесть совпадение прямых и посчитать решения','При a=0 прямые совпадают, получаем (0,0) и (2,0). При a≠0 ненулевые кандидаты разных прямых различны. Если |a|>3, допустим ровно один из них; если 0<|a|≤3, обычно оба, кроме a=±1/3, когда один сливается с O.',['count'],['s2','s3']),
 ('Записать все параметры с ровно двумя решениями','a=0, a=±1/3 или |a|>3. При a=±3 оба ненулевых кандидата допустимы, поэтому эти границы исключены.',['sets'],['s4'])],
 [('radical','Снимать равенство квадратных корней','При неотрицательных радикандах заменить равенство корней равенством радикандов; область сохранить отдельно.'),
 ('domain','Сохранять область определения квадратных корней','Потребовать неотрицательность всех радикандов и проверить кандидатов после алгебраических преобразований.'),
 ('sub','Исключать переменную подстановкой из линейной связи','Подставить y=mx в другое уравнение, сохраняя равносильность и ограничения.'),
 ('factor','Решать уравнение через нулевое произведение','Выделить нулевой корень и остальные множители, не теряя случай нуля делением.'),
 ('rationalineq','Решать рациональное неравенство с положительным знаменателем','Доказать положительность знаменателя, умножить без смены знака и решить оставшееся неравенство.'),
 ('count','Считать различные решения объединения ветвей','Проверить допустимость кандидатов, совпадение ветвей и общие решения; не складывать количества без учёта пересечений.'),
 ('sets','Записывать множество параметров с граничными случаями','Объединить найденные случаи и отдельно проверить равенства на границах.')],
 [('Разбить на две прямые и исследовать их пересечения с окружностью',[1,2,3,4,5])])
